// Generated by AI (UnitTest MCP)
//! Deterministic symbol and call-graph extraction (heuristic, zero-token).
//!
//! Pattern-based extraction covering the common languages. It finds symbol
//! **definitions** and, within each callable definition's body, **call sites**
//! that reference another symbol defined in the same file — emitting in-file
//! `calls` edges. Structured behind [`extract`] so a Tree-sitter backend can
//! replace the heuristics later (for cross-file / scope-accurate resolution)
//! without touching callers.

use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex, OnceLock};

use regex::Regex;

use crate::ingest::javascript::{
    callable_for_definition, is_identifier_shadowed, is_identifier_shadowed_except,
    mask_non_code as mask_javascript_non_code, next_non_newline, previous_non_newline, tokenize,
    Token,
};
use crate::ingest::source_mask::mask_non_code as mask_source_non_code;

/// A source symbol definition discovered in a file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Symbol {
    pub name: String,
    /// Stable identity within the file, qualified by a lexical owner when one
    /// exists (for example `GraphStore::new`).
    pub qualified_name: String,
    pub kind: String,
    pub line: usize,
}

/// An in-file call between qualified symbol identities defined in the file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Call {
    pub caller: String,
    pub callee: String,
}

/// A call to a name that is not defined in the current file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CallReference {
    pub caller: String,
    pub callee: String,
}

/// The result of analysing one file.
#[derive(Debug, Clone, Default)]
pub struct Extraction {
    pub symbols: Vec<Symbol>,
    pub calls: Vec<Call>,
    pub call_references: Vec<CallReference>,
}

/// Internal definition record with the byte offset of its name.
struct Def {
    name: String,
    qualified_name: String,
    owner: Option<String>,
    kind: String,
    line: usize,
    name_offset: usize,
}

/// Kinds that can contain calls (i.e. have a body worth scanning).
const CALLABLE_KINDS: &[&str] = &["fn", "function", "arrow", "def", "func", "method"];

/// Per-language definition patterns and whether the language is brace-scoped
/// (`true`) or indentation-scoped (`false`, e.g. Python).
fn language_config(ext: &str) -> (&'static [(&'static str, &'static str)], bool) {
    match ext {
        "rs" => (
            &[
                (
                    r#"(?m)^\s*(?:pub(?:\s*\([^)]*\))?\s+)?(?:(?:const|async|unsafe|extern(?:\s+"[^"]*"))\s+)*fn\s+([A-Za-z_]\w*)"#,
                    "fn",
                ),
                (
                    r"(?m)^\s*(?:pub(?:\s*\([^)]*\))?\s+)?struct\s+([A-Za-z_]\w*)",
                    "struct",
                ),
                (
                    r"(?m)^\s*(?:pub(?:\s*\([^)]*\))?\s+)?enum\s+([A-Za-z_]\w*)",
                    "enum",
                ),
                (
                    r"(?m)^\s*(?:pub(?:\s*\([^)]*\))?\s+)?trait\s+([A-Za-z_]\w*)",
                    "trait",
                ),
            ],
            true,
        ),
        "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" => (
            &[
                (
                    r"(?m)^\s*(?:export\s+)?(?:default\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)",
                    "function",
                ),
                (
                    r"(?m)^\s*(?:export\s+)?(?:abstract\s+)?class\s+([A-Za-z_$][\w$]*)",
                    "class",
                ),
                (
                    r"(?m)^\s*(?:export\s+)?interface\s+([A-Za-z_$][\w$]*)",
                    "interface",
                ),
                (
                    r"(?m)^\s*(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?\(",
                    "arrow",
                ),
            ],
            true,
        ),
        "py" => (
            &[
                (r"(?m)^\s*def\s+([A-Za-z_]\w*)", "def"),
                (r"(?m)^\s*class\s+([A-Za-z_]\w*)", "class"),
            ],
            false,
        ),
        "cs" => (
            &[(
                r"(?m)(?:class|interface|struct|record|enum)\s+([A-Za-z_]\w*)",
                "type",
            )],
            true,
        ),
        "go" => (
            &[
                (r"(?m)^\s*func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)", "func"),
                (r"(?m)^\s*type\s+([A-Za-z_]\w*)", "type"),
            ],
            true,
        ),
        "java" | "kt" => (
            &[(r"(?m)(?:class|interface|enum)\s+([A-Za-z_]\w*)", "type")],
            true,
        ),
        _ => (&[], true),
    }
}

fn find_defs(content: &str, patterns: &[(&str, &str)]) -> Vec<Def> {
    let mut defs = Vec::new();
    for (pattern, kind) in patterns {
        let re = match compiled_pattern(pattern) {
            Some(re) => re,
            None => continue,
        };
        for caps in re.captures_iter(content) {
            if let Some(m) = caps.get(1) {
                let line = 1 + content[..m.start()].bytes().filter(|&b| b == b'\n').count();
                defs.push(Def {
                    name: m.as_str().to_string(),
                    qualified_name: m.as_str().to_string(),
                    owner: None,
                    kind: (*kind).to_string(),
                    line,
                    name_offset: m.start(),
                });
            }
        }
    }
    defs
}

/// Compile each language's constant definition pattern once and reuse it across
/// files, keyed by the pattern text. `find_defs` previously recompiled every
/// pattern on every call; a pattern that fails to compile is still skipped
/// (`None`) and never cached, exactly as before.
fn compiled_pattern(pattern: &str) -> Option<Arc<Regex>> {
    static CACHE: OnceLock<Mutex<HashMap<String, Arc<Regex>>>> = OnceLock::new();
    let mut cache = CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(re) = cache.get(pattern) {
        return Some(Arc::clone(re));
    }
    let re = Arc::new(Regex::new(pattern).ok()?);
    cache.insert(pattern.to_string(), Arc::clone(&re));
    Some(re)
}

#[derive(Debug)]
struct OwnerSpan {
    name: String,
    start: usize,
    end: usize,
}

fn qualify_rust_methods(content: &str, defs: &mut [Def]) {
    let owners = rust_impl_owner_spans(content);
    for def in defs.iter_mut().filter(|definition| definition.kind == "fn") {
        let owner = owners
            .iter()
            .filter(|owner| def.name_offset >= owner.start && def.name_offset < owner.end)
            .min_by_key(|owner| owner.end - owner.start);
        if let Some(owner) = owner {
            def.owner = Some(owner.name.clone());
            def.qualified_name = format!("{}::{}", owner.name, def.name);
        }
    }
}

fn rust_impl_owner_spans(content: &str) -> Vec<OwnerSpan> {
    rust_impl_re()
        .captures_iter(content)
        .filter_map(|capture| {
            let complete = capture.get(0)?;
            let header = capture.get(1)?.as_str();
            let open = complete.end().checked_sub(1)?;
            let end = matching_brace_end(content, open)?;
            Some(OwnerSpan {
                name: rust_impl_identity(header)?,
                start: open + 1,
                end,
            })
        })
        .collect()
}

fn rust_impl_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(r"(?ms)^[ \t]*(?:unsafe[ \t]+)?impl\b(.*?)\{").expect("valid Rust impl regex")
    })
}

fn rust_impl_identity(header: &str) -> Option<String> {
    let header = header.split_whitespace().collect::<Vec<_>>().join(" ");
    let header = strip_leading_generics(header.trim());
    let header = header.split(" where ").next()?.trim();
    if let Some((trait_name, target)) = header.rsplit_once(" for ") {
        Some(format!(
            "{}::{}",
            rust_type_name(target)?,
            rust_type_name(trait_name)?
        ))
    } else {
        rust_type_name(header)
    }
}

fn strip_leading_generics(value: &str) -> &str {
    if !value.starts_with('<') {
        return value;
    }
    let mut depth = 0usize;
    for (index, character) in value.char_indices() {
        match character {
            '<' => depth += 1,
            '>' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return value[index + character.len_utf8()..].trim_start();
                }
            }
            _ => {}
        }
    }
    value
}

fn rust_type_name(value: &str) -> Option<String> {
    let without_generics = value.split('<').next()?.trim();
    let path = without_generics
        .split_whitespace()
        .last()?
        .trim_matches(|character: char| {
            !character.is_ascii_alphanumeric() && character != '_' && character != ':'
        });
    path.rsplit("::")
        .find(|segment| !segment.is_empty())
        .map(str::to_string)
}

fn matching_brace_end(content: &str, open: usize) -> Option<usize> {
    let mut depth = 0usize;
    for (index, byte) in content.as_bytes().iter().enumerate().skip(open) {
        match byte {
            b'{' => depth += 1,
            b'}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(index);
                }
            }
            _ => {}
        }
    }
    None
}

/// Compute the `[start, end)` byte span of a definition's body.
fn body_span(
    content: &str,
    def: &Def,
    brace_lang: bool,
    javascript: bool,
) -> Option<(usize, usize)> {
    if javascript {
        let tokens = tokenize(content);
        let definition = tokens.iter().position(|token| {
            token.start >= def.name_offset && token.identifier() == Some(def.name.as_str())
        })?;
        let callable = callable_for_definition(&tokens, definition, &def.kind)?;
        Some((
            tokens[callable.body_open].end,
            tokens[callable.body_close].start,
        ))
    } else if brace_lang {
        let open = content[def.name_offset..].find('{')? + def.name_offset;
        matching_brace_end(content, open).map(|end| (open + 1, end))
    } else {
        // Indentation-scoped (Python): body = following lines indented deeper
        // than the definition line.
        let line_start = content[..def.name_offset]
            .rfind('\n')
            .map(|p| p + 1)
            .unwrap_or(0);
        let def_indent = content[line_start..]
            .chars()
            .take_while(|c| *c == ' ' || *c == '\t')
            .count();
        let body_start = content[def.name_offset..]
            .find('\n')
            .map(|p| p + def.name_offset + 1)?;
        let mut pos = body_start;
        let mut end = content.len();
        while pos < content.len() {
            let line_end = content[pos..]
                .find('\n')
                .map(|p| p + pos)
                .unwrap_or(content.len());
            let line = &content[pos..line_end];
            if !line.trim_start().is_empty() {
                let indent = line.chars().take_while(|c| *c == ' ' || *c == '\t').count();
                if indent <= def_indent {
                    end = pos;
                    break;
                }
            }
            pos = line_end + 1;
        }
        Some((body_start, end))
    }
}

/// Analyse a file into symbol definitions and in-file call edges.
pub fn extract(path: &str, content: &str) -> Extraction {
    let ext = path.rsplit('.').next().unwrap_or("").to_ascii_lowercase();
    let javascript = matches!(ext.as_str(), "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs");
    let (patterns, brace_lang) = language_config(&ext);
    let masked = if javascript {
        mask_javascript_non_code(content)
    } else {
        mask_source_non_code(&ext, content)
    };
    let mut defs = find_defs(&masked, patterns);
    if ext == "rs" {
        qualify_rust_methods(&masked, &mut defs);
    }

    let symbols: Vec<Symbol> = defs
        .iter()
        .map(|d| Symbol {
            name: d.name.clone(),
            qualified_name: d.qualified_name.clone(),
            kind: d.kind.clone(),
            line: d.line,
        })
        .collect();

    let mut callable_defs: HashMap<&str, Vec<&Def>> = HashMap::new();
    for definition in defs
        .iter()
        .filter(|definition| CALLABLE_KINDS.contains(&definition.kind.as_str()))
    {
        callable_defs
            .entry(definition.name.as_str())
            .or_default()
            .push(definition);
    }

    // Body spans for callable definitions (for innermost-caller attribution).
    let bodies: Vec<(&Def, usize, usize)> = defs
        .iter()
        .filter(|d| CALLABLE_KINDS.contains(&d.kind.as_str()))
        .filter_map(|d| {
            let body_source = if javascript { content } else { &masked };
            body_span(body_source, d, brace_lang, javascript).map(|(start, end)| (d, start, end))
        })
        .collect();

    let def_offsets: HashSet<usize> = defs.iter().map(|d| d.name_offset).collect();

    let mut calls = Vec::new();
    let mut call_references = Vec::new();
    let mut seen: HashSet<(String, String)> = HashSet::new();
    let mut references_seen: HashSet<(String, String)> = HashSet::new();
    if !bodies.is_empty() {
        let javascript_tokens = javascript.then(|| tokenize(content));
        let call_sites = if let Some(tokens) = &javascript_tokens {
            javascript_call_sites(tokens)
        } else {
            regex_call_sites(&masked)
        };
        for (callee, offset, token_index) in call_sites {
            // Definition signatures look like calls to the regex.
            if def_offsets.contains(&offset) {
                continue;
            }
            let caller = bodies
                .iter()
                .filter(|(_, start, end)| offset >= *start && offset < *end)
                .min_by_key(|(_, start, end)| end - start)
                .map(|(definition, _, _)| *definition);
            if let Some(caller) = caller {
                let local_candidates = callable_defs
                    .get(callee.as_str())
                    .map(Vec::as_slice)
                    .unwrap_or_default();
                let local_definition = resolve_local_definition(local_candidates, caller);
                let shadowed = match (&javascript_tokens, token_index) {
                    (Some(tokens), Some(index)) => {
                        if let Some(definition) = local_definition {
                            is_identifier_shadowed_except(
                                tokens,
                                index,
                                &callee,
                                Some(definition.name_offset),
                            )
                        } else {
                            is_identifier_shadowed(tokens, index, &callee)
                        }
                    }
                    _ => false,
                };
                if shadowed {
                    continue;
                }
                if let Some(local_definition) = local_definition {
                    if caller.qualified_name == local_definition.qualified_name {
                        continue;
                    }
                    let edge = (
                        caller.qualified_name.clone(),
                        local_definition.qualified_name.clone(),
                    );
                    if seen.insert(edge.clone()) {
                        calls.push(Call {
                            caller: edge.0,
                            callee: edge.1,
                        });
                    }
                } else if local_candidates.is_empty()
                    && references_seen.insert((caller.qualified_name.clone(), callee.clone()))
                {
                    call_references.push(CallReference {
                        caller: caller.qualified_name.clone(),
                        callee,
                    });
                }
            }
        }
    }

    Extraction {
        symbols,
        calls,
        call_references,
    }
}

fn resolve_local_definition<'a>(candidates: &[&'a Def], caller: &Def) -> Option<&'a Def> {
    if candidates.len() == 1 {
        return candidates.first().copied();
    }
    let mut same_owner = candidates
        .iter()
        .copied()
        .filter(|candidate| candidate.owner == caller.owner);
    let resolved = same_owner.next()?;
    same_owner.next().is_none().then_some(resolved)
}

fn regex_call_sites(content: &str) -> Vec<(String, usize, Option<usize>)> {
    call_site_re()
        .captures_iter(content)
        .filter_map(|captures| {
            captures
                .get(1)
                .map(|matched| (matched.as_str().to_string(), matched.start(), None))
        })
        .collect()
}

/// An identifier immediately followed by `(` — a heuristic call site. Compiled
/// once rather than on every extraction.
fn call_site_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"([A-Za-z_$][\w$]*)\s*\(").expect("valid call regex"))
}

fn javascript_call_sites(tokens: &[Token]) -> Vec<(String, usize, Option<usize>)> {
    let mut sites = Vec::new();
    for (index, token) in tokens.iter().enumerate() {
        let Some(name) = token.identifier() else {
            continue;
        };
        let Some(next) = next_non_newline(tokens, index + 1) else {
            continue;
        };
        if !tokens[next].is_punctuation('(') {
            continue;
        }
        if previous_non_newline(tokens, index)
            .is_some_and(|previous| tokens[previous].is_punctuation('.'))
        {
            continue;
        }
        sites.push((name.to_string(), token.start, Some(index)));
    }
    sites
}

/// Extract just the symbol definitions from `content` (convenience wrapper).
pub fn extract_symbols(path: &str, content: &str) -> Vec<Symbol> {
    extract(path, content).symbols
}

/// Doc-comment lines kept above a declaration. Enough for an intent sentence,
/// short enough that a long licence header never becomes the symbol's meaning.
const MAX_DOC_LINES: usize = 8;
/// Characters kept. Embedding quality falls off well before this, and an
/// unbounded body would let one enormous signature dominate a batch.
const MAX_CONTEXT_CHARS: usize = 400;

/// The text worth embedding for a symbol: its declaration line, plus any doc
/// comment written immediately above it.
///
/// Symbol nodes stored `path:line` and nothing else, so the only thing an
/// embedding could see was the symbol's *name*. That made terse implementation
/// names (`effective_weight`, `prune`, `recall`) embed as near-noise while long
/// descriptive test names embedded richly — so `recall` systematically returned
/// the tests instead of the code under test. Measured: querying the literal
/// identifier `effective_weight` did not return `effective_weight`.
///
/// Deterministic and zero-token: this is text already parsed off disk, never a
/// model call (invariant 1).
///
/// `line` is 1-based, matching [`Symbol::line`].
pub fn symbol_context(content: &str, line: usize) -> String {
    let lines: Vec<&str> = content.lines().collect();
    let Some(index) = line.checked_sub(1).filter(|index| *index < lines.len()) else {
        return String::new();
    };

    let mut kept: Vec<&str> = Vec::new();
    let mut cursor = index;
    while cursor > 0 && kept.len() < MAX_DOC_LINES {
        let candidate = lines[cursor - 1].trim();
        if is_attribute(candidate) {
            // Attributes sit between the doc comment and the declaration; step
            // over them rather than stopping, or `#[inline]` would hide the doc.
            cursor -= 1;
            continue;
        }
        if !is_doc_comment(candidate) {
            break;
        }
        kept.push(candidate);
        cursor -= 1;
    }
    kept.reverse();
    kept.push(lines[index].trim());

    let joined = kept.join("\n");
    match joined.char_indices().nth(MAX_CONTEXT_CHARS) {
        Some((boundary, _)) => joined[..boundary].to_string(),
        None => joined,
    }
}

/// A comment line in any of the languages the extractor covers.
fn is_doc_comment(line: &str) -> bool {
    line.starts_with("//")
        || line.starts_with("/*")
        || line.starts_with('*')
        || line.starts_with("\"\"\"")
        // `#` is a comment in Python, Ruby, and shell -- but `#[` and `#!` are
        // Rust attributes, which `is_attribute` handles separately.
        || (line.starts_with('#') && !line.starts_with("#[") && !line.starts_with("#!"))
}

/// A Rust attribute, which separates a doc comment from its declaration.
fn is_attribute(line: &str) -> bool {
    line.starts_with("#[") || line.starts_with("#![")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compiled_pattern_caches_and_reuses_the_same_regex() {
        let a = compiled_pattern(r"^\s*fn\s+(\w+)").expect("valid pattern");
        let b = compiled_pattern(r"^\s*fn\s+(\w+)").expect("valid pattern");
        // Same pattern text -> the same cached instance, not a fresh compile.
        assert!(Arc::ptr_eq(&a, &b));
        // A malformed pattern is skipped, exactly as the old Regex::new match.
        assert!(compiled_pattern(r"(").is_none());
    }

    #[test]
    fn symbol_context_keeps_the_declaration_and_its_doc_comment() {
        // The regression: a symbol embedded as its name alone, so querying the
        // literal identifier `effective_weight` did not return it.
        let source = "\
/// The half-life decay applied at read time.
/// Never stored, always derived.
pub fn effective_weight(base: f64, age_hours: f64) -> f64 {
    base
}
";
        let context = symbol_context(source, 3);

        assert!(context.contains("The half-life decay applied at read time."));
        assert!(context.contains("Never stored, always derived."));
        assert!(context.contains("pub fn effective_weight"));
    }

    #[test]
    fn symbol_context_steps_over_attributes_to_reach_the_doc() {
        let source = "\
/// Reap decayed edges.
#[inline]
pub fn prune() {}
";
        let context = symbol_context(source, 3);

        assert!(context.contains("Reap decayed edges."));
        assert!(context.contains("pub fn prune"));
    }

    #[test]
    fn symbol_context_stops_at_unrelated_code() {
        // A blank line or a previous statement is not this symbol's doc.
        let source = "\
let unrelated = 1;

pub fn recall() {}
";
        let context = symbol_context(source, 3);

        assert_eq!(context, "pub fn recall() {}");
    }

    #[test]
    fn symbol_context_handles_hash_comments_but_not_rust_attributes() {
        let python = "# Build the working set.\ndef working_set():\n    pass\n";
        assert!(symbol_context(python, 2).contains("Build the working set."));

        let rust = "#[derive(Debug)]\npub struct Node;\n";
        assert_eq!(symbol_context(rust, 2), "pub struct Node;");
    }

    #[test]
    fn symbol_context_is_bounded_and_survives_a_line_past_the_end() {
        let long = format!("/// {}\npub fn wide() {{}}\n", "x".repeat(2_000));
        assert!(symbol_context(&long, 2).chars().count() <= MAX_CONTEXT_CHARS);

        assert_eq!(symbol_context("pub fn only() {}", 99), "");
        assert_eq!(symbol_context("", 0), "");
    }

    #[test]
    fn extracts_rust_symbols() {
        let src = "pub fn validate_session() {}\nstruct Session {}\n";
        let syms = extract_symbols("src/auth.rs", src);
        assert!(syms
            .iter()
            .any(|s| s.name == "validate_session" && s.kind == "fn"));
        assert!(syms
            .iter()
            .any(|s| s.name == "Session" && s.kind == "struct"));
    }

    #[test]
    fn extracts_typescript_symbols() {
        let src = "export function validateSession() {}\nclass Auth {}\nexport const run = async () => {}\n";
        let syms = extract_symbols("src/auth.ts", src);
        assert!(syms.iter().any(|s| s.name == "validateSession"));
        assert!(syms.iter().any(|s| s.name == "Auth" && s.kind == "class"));
        assert!(syms.iter().any(|s| s.name == "run" && s.kind == "arrow"));
    }

    #[test]
    fn line_numbers_are_one_based() {
        let src = "\n\ndef helper():\n    pass\n";
        let syms = extract_symbols("x.py", src);
        assert_eq!(syms[0].line, 3);
    }

    #[test]
    fn unknown_extension_yields_nothing() {
        assert!(extract_symbols("data.bin", "garbage").is_empty());
    }

    #[test]
    fn extracts_rust_call_edges() {
        let src = "fn a() {\n    b();\n    helper();\n}\nfn b() {}\nfn helper() {}\n";
        let calls = extract("src/x.rs", src).calls;
        assert!(calls.contains(&Call {
            caller: "a".into(),
            callee: "b".into()
        }));
        assert!(calls.contains(&Call {
            caller: "a".into(),
            callee: "helper".into()
        }));
    }

    #[test]
    fn extracts_python_call_edges() {
        let src = "def a():\n    b()\n\ndef b():\n    pass\n";
        let calls = extract("m.py", src).calls;
        assert_eq!(
            calls,
            vec![Call {
                caller: "a".into(),
                callee: "b".into()
            }]
        );
    }

    #[test]
    fn ignores_self_recursion_and_unknown_callees() {
        let src = "fn a() {\n    a();\n    unknown_fn();\n}\n";
        let calls = extract("src/x.rs", src).calls;
        assert!(calls.is_empty()); // self-loop skipped; unknown_fn not defined here
    }

    #[test]
    fn separates_unresolved_references_from_in_file_calls() {
        let src = "fn caller() {\n    local();\n    imported();\n}\nfn local() {}\n";
        let extraction = extract("src/x.rs", src);

        assert_eq!(
            extraction.calls,
            vec![Call {
                caller: "caller".into(),
                callee: "local".into(),
            }]
        );
        assert_eq!(
            extraction.call_references,
            vec![CallReference {
                caller: "caller".into(),
                callee: "imported".into(),
            }]
        );
    }

    #[test]
    fn javascript_references_ignore_comments_strings_members_and_shadowing() {
        let source = r#"
export function caller(dependency) {
    // dependency();
    const text = "dependency()";
    other.dependency();
    dependency();
}
export function localShadow() {
    const dependency = () => {};
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(!extraction
            .call_references
            .iter()
            .any(|reference| reference.callee == "dependency"));
    }

    #[test]
    fn javascript_body_span_ignores_braces_in_strings_comments_and_templates() {
        let source = r#"
export function consumer() {
    const close = "}";
    const open = `{`;
    // }
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn nested_shadow_does_not_hide_outer_imported_call() {
        let source = r#"
export function consumer() {
    dependency();
    if (condition) {
        const dependency = local;
        dependency();
    }
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert_eq!(
            extraction
                .call_references
                .iter()
                .filter(|reference| reference.callee == "dependency")
                .count(),
            1
        );
    }

    #[test]
    fn javascript_local_function_call_is_not_filtered_as_shadowed() {
        let source = "export function caller() { callee(); }\nfunction callee() {}\n";
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.calls.contains(&Call {
            caller: "caller".to_string(),
            callee: "callee".to_string(),
        }));
    }

    #[test]
    fn parameter_shadow_prevents_false_same_file_call() {
        let source = "function dependency() {}\nfunction caller(dependency) { dependency(); }\n";
        let extraction = extract("src/consumer.ts", source);

        assert!(!extraction
            .calls
            .iter()
            .any(|call| { call.caller == "caller" && call.callee == "dependency" }));
    }

    #[test]
    fn property_and_type_names_are_not_parameter_bindings() {
        let source = r#"
export function consumer({ dependency: local }, value: typeof Factory) {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn destructured_parameters_and_typed_return_keep_real_body_span() {
        let source = r#"
export function consumer({ flag }): void {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn default_arrow_parameter_and_function_type_return_keep_outer_body() {
        let source = r#"
export const arrowConsumer = (callback = () => {}) => {
    dependency();
};
export function typedConsumer(): () => { value: string } {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "arrowConsumer".to_string(),
            callee: "dependency".to_string(),
        }));
        assert!(extraction.call_references.contains(&CallReference {
            caller: "typedConsumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn comments_and_templates_do_not_create_symbol_definitions() {
        let source = r#"
/*
function ghostFromComment() {}
*/
const text = `
function ghostFromTemplate() {}
`;
export function real() {}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert_eq!(
            extraction
                .symbols
                .iter()
                .map(|symbol| symbol.name.as_str())
                .collect::<Vec<_>>(),
            vec!["real"]
        );
    }

    #[test]
    fn attributes_call_to_innermost_definition() {
        // A call inside `b` must be attributed to b, not the earlier `a`.
        let src = "fn a() {}\nfn b() {\n    a();\n}\n";
        let calls = extract("src/x.rs", src).calls;
        assert_eq!(
            calls,
            vec![Call {
                caller: "b".into(),
                callee: "a".into()
            }]
        );
    }
}
